test("the invitation client wires the draft-clearing predicate before navigating away", async () => {
  const source = await readFile("src/app/partner/einladung/partner-invitation-client.tsx", "utf8")
  assert.match(source, /shouldClearQuizDraft\(body\)/)
  assert.match(source, /clearQuizDraft\(\)/)
  const guardIndex = source.indexOf("isDestination(body)")
  const clearIndex = source.indexOf("clearQuizDraft()")
  const assignIndex = source.indexOf("window.location.assign(body.destination)")
  assert.ok(
    guardIndex > 0 && clearIndex > guardIndex && assignIndex > clearIndex,
    "draft must be cleared after the destination guard and before navigating",
  )
})

test("partner activation requires exact authorization and sends ready email only once", async () => {
  const calls: string[] = []
  const response = await createPartnerActivateHandler({
    getUserId: async () => ids.user,
    authorize: async () => ({
      invitationId: ids.invitation,
      userId: ids.user,
      funnelSessionId: ids.funnel,
      leadId: ids.lead,
    }),
    activate: async () => ({ grantId: "grant", reused: false }),
    resolveDestinationLeadId: async (_userId, partnerLeadId) => partnerLeadId,
    sendReadyEmail: async () => {
      calls.push("ready-email")
      return true
    },
  })(request())
  assert.equal(response.status, 200)
  assert.deepEqual(await response.json(), { destination: `/plan-bereit?lead=${ids.lead}` })
  await new Promise((resolve) => setImmediate(resolve))
  assert.deepEqual(calls, ["ready-email"])

  const denied = await createPartnerActivateHandler({
    getUserId: async () => ids.user,
    authorize: async () => null,
  })(request())
  assert.equal(denied.status, 403)
})

test("partner activation requires no funnel cookie — authorization is resolved from the user and lead alone", async () => {
  const authorizeCalls: unknown[] = []
  const response = await createPartnerActivateHandler({
    getUserId: async () => ids.user,
    authorize: async (input) => {
      authorizeCalls.push(input)
      return {
        invitationId: ids.invitation,
        userId: ids.user,
        funnelSessionId: ids.funnel,
        leadId: ids.lead,
      }
    },
    activate: async () => ({ grantId: "grant", reused: true }),
    resolveDestinationLeadId: async (_userId, partnerLeadId) => partnerLeadId,
    sendReadyEmail: async () => true,
  })(request())
  assert.equal(response.status, 200)
  assert.deepEqual(authorizeCalls, [{ userId: ids.user, leadId: ids.lead }])
})

test("partner activation sends an existing paid creator to their canonical plan lead", async () => {
  const response = await createPartnerActivateHandler({
    getUserId: async () => ids.user,
    authorize: async () => ({
      invitationId: ids.invitation,
      userId: ids.user,
      funnelSessionId: ids.funnel,
      leadId: ids.lead,
    }),
    activate: async () => ({ grantId: "grant", reused: false }),
    sendReadyEmail: async () => true,
    resolveDestinationLeadId: async (userId, partnerLeadId) => {
      assert.equal(userId, ids.user)
      assert.equal(partnerLeadId, ids.lead)
      return ids.paidLead
    },
  })(request())

  assert.equal(response.status, 200)
  assert.deepEqual(await response.json(), {
    destination: `/plan-bereit?lead=${ids.paidLead}`,
  })
  assert.equal(
    resolvePartnerActivationDestinationLead(
      { accessState: "active", artifactLeadId: ids.paidLead },
      ids.lead,
    ),
    ids.paidLead,
  )
  assert.equal(
    resolvePartnerActivationDestinationLead(
      { accessState: "none", artifactLeadId: null },
      ids.lead,
    ),
    ids.lead,
  )
})

