test("email correction rejects cross-origin, stale, unchanged, and throttled requests", async () => {
  const handler = createPartnerEmailChangeHandler(dependencies())
  assert.equal((await handler(request("new@example.test", "https://evil.example"))).status, 403)
  assert.equal((await handler(request("lea@example.test"))).status, 400)

  const stale = createPartnerEmailChangeHandler(
    dependencies({ loadInvitation: async () => ({ ...invitation, token_version: 2 }) }),
  )
  assert.equal((await stale(request("new@example.test"))).status, 410)

  const throttled = createPartnerEmailChangeHandler(
    dependencies({
      issue: async () => {
        throw Object.assign(new Error("rate limited"), { code: "55P03" })
      },
    }),
  )
  const throttledResponse = await throttled(request("new@example.test"))
  assert.equal(throttledResponse.status, 429)
  assert.deepEqual(await throttledResponse.json(), {
    error: "Bitte warte kurz und versuche es dann noch einmal.",
  })
})

test("email confirmation returns a fresh fragment credential and fails closed", async () => {
  const confirmRequest = () =>
    new Request("https://chaarlie.de/api/partner-access/email-change/confirm", {
      method: "POST",
      headers: { origin: "https://chaarlie.de", "content-type": "application/json" },
      body: JSON.stringify({ token: "mailbox-proof" }),
    })
  const response = await createPartnerEmailChangeConfirmHandler({
    consume: async () => ({
      invitationId,
      name: "Lea Sommer",
      email: "new@example.test",
      tokenVersion: 2,
    }),
    projectCredential: () => "fresh-credential",
    secret: () => "partner-access-signing-secret-that-is-long-enough",
  })(confirmRequest())
  assert.equal(response.status, 200)
  assert.deepEqual(await response.json(), {
    destination: "/partner/einladung?bestaetigt=1#code=fresh-credential",
  })

  const unavailable = createPartnerEmailChangeConfirmHandler({
    consume: async () => {
      throw new Error("expired")
    },
    secret: () => "partner-access-signing-secret-that-is-long-enough",
  })
  assert.equal((await unavailable(confirmRequest())).status, 410)
})

test("partner invitation credentials are deterministic, versioned, and tamper evident", () => {
  const first = projectPartnerInvitationCredential({ invitationId, tokenVersion: 4 }, secret)
  const replay = projectPartnerInvitationCredential({ invitationId, tokenVersion: 4 }, secret)

  assert.equal(first, replay)
  assert.match(first, /^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/)
  assert.deepEqual(decodePartnerInvitationCredential(first, secret), {
    invitationId,
    tokenVersion: 4,
  })
  assert.equal(decodePartnerInvitationCredential(`${first}x`, secret), null)
  assert.equal(decodePartnerInvitationCredential(first, `${secret}-wrong`), null)
})

test("rotating the stored version invalidates the previous credential", () => {
  const previous = projectPartnerInvitationCredential({ invitationId, tokenVersion: 1 }, secret)
  const current = projectPartnerInvitationCredential({ invitationId, tokenVersion: 2 }, secret)

  assert.notEqual(previous, current)
  assert.equal(decodePartnerInvitationCredential(previous, secret)?.tokenVersion, 1)
  assert.equal(decodePartnerInvitationCredential(current, secret)?.tokenVersion, 2)
})

test("credentials reject malformed identifiers, versions, and weak secrets", () => {
  assert.throws(
    () => projectPartnerInvitationCredential({ invitationId: "nope", tokenVersion: 1 }, secret),
    /invitation/i,
  )
  assert.throws(
    () => projectPartnerInvitationCredential({ invitationId, tokenVersion: 0 }, secret),
    /version/i,
  )
  assert.throws(
    () => projectPartnerInvitationCredential({ invitationId, tokenVersion: 1 }, "short"),
    /secret/i,
  )
})

